{{-- Add plugin initialization and configuration code --}}

@push('js')
<script>

    (() => {

    let initSelect2 = () => {
        let $el = $('#{{ $id }}');

        if ($el.length === 0) {
            return;
        }

        // Livewire morphs this markup on every component update, which strips
        // the container generated by the plugin. Rebuilding from the morphed
        // select also picks up the value Livewire just applied to its options,
        // so the widget can never display stale text.

        if ($el.data('select2')) {
            $el.select2('destroy');
        }

        // Inside a Bootstrap modal the plugin must render its dropdown inside
        // the modal itself. Appended to <body> (the plugin default) the
        // dropdown sits outside the modal's focus trap, so Bootstrap's
        // enforceFocus keeps stealing focus back and the dropdown's search
        // box can never be typed into. Pointing dropdownParent at the
        // closest modal keeps the dropdown inside the trap.

        let config = @json($config);

        let $modal = $el.closest('.modal');

        if ($modal.length > 0) {
            config.dropdownParent = $modal;
        }

        $el.select2(config);

        // select2 4.0.13 measures the dropdown's position once, when it opens,
        // and never again - it registers no scroll or resize listener. On any
        // scrolling page (this modal, the content wrapper, the window) the
        // field keeps moving while the dropdown's coordinates stay frozen, so
        // the dropdown detaches: it drags the dialog body along with the other
        // inputs, and once stale it can open under the cursor, which selects a
        // value the officer never clicked.
        //
        // The helper re-measures the dropdown against its field on every

        if (window.THHASelect2Scroll) {
            window.THHASelect2Scroll.follow($el);
        }

        // The plugin writes its value through jQuery, and jQuery's
        // .trigger('change') does not dispatch a native event - the kind
        // Livewire's wire:model listens to. Forward the selection as a real
        // DOM event so the component state follows the widget.

        $el.off('.select2Bridge').on(
            'select2:select.select2Bridge select2:unselect.select2Bridge select2:clear.select2Bridge',
            (event) => event.target.dispatchEvent(new Event('change', { bubbles: true }))
        );
    };

    $(() => {
        initSelect2();

        if (window.Livewire) {
            Livewire.hook('message.processed', initSelect2);
        }

        // Add support to auto select old submitted values in case of
        // validation errors.

        @if($errors->any() && $enableOldSupport)

            let oldOptions = @json(collect($getOldValue($errorKey)));

            $('#{{ $id }} option').each(function()
            {
                let value = $(this).val() || $(this).text();
                $(this).prop('selected', oldOptions.includes(value));
            });

            $('#{{ $id }}').trigger('change');

        @endif
    })

    })();

</script>
@endpush

